CREATE TABLE IF NOT EXISTS `exam_attempts` (`id` int NOT NULL AUTO_INCREMENT,`userId` int NOT NULL,`grade` varchar(32) NOT NULL,`track` varchar(32) NOT NULL,`subject` varchar(128) NOT NULL,`chapter` varchar(128) NOT NULL,`questionCount` int NOT NULL,`correctCount` int NOT NULL,`scorePercent` int NOT NULL,`responses` json NOT NULL,`topicAnalysis` json NOT NULL,`completedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),KEY `exam_attempts_user_id_idx` (`userId`),KEY `exam_attempts_user_subject_idx` (`userId`,`subject`),KEY `exam_attempts_user_chapter_idx` (`userId`,`chapter`));
